 static String hash(String value)throws Exception{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}
 static Object normalize(Object value){if(value instanceof Map<?,?> m){var result=new TreeMap<String,Object>();m.forEach((k,v)->result.put(k.toString(),normalize(v)));return result;}if(value instanceof List<?> l)return l.stream().map(Task11B2ReceiptApi::normalize).toList();if(value instanceof java.time.temporal.TemporalAccessor||value instanceof java.util.Date)return value.toString();if(value instanceof byte[] b)return Base64.getEncoder().encodeToString(b);return value;}
 public static Map<String,String> business(JdbcTemplate j)throws Exception {var result=new TreeMap<String,String>();for(String t:List.of("meeting","final_confirmation","final_result_review","publication","publication_submission","external_document_mapping","publication_attempt","durable_task","task_attempt","external_operation","external_execution","idempotency_record","audit_event","task_outbox","task_outbox_sequence","task_subject","meeting_search_projection")){var keys=j.queryForList("SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? AND CONSTRAINT_NAME='PRIMARY' ORDER BY ORDINAL_POSITION",String.class,t);assertFalse(keys.isEmpty());result.put(t,hash(JSON.writeValueAsString(normalize(j.queryForList("SELECT * FROM "+t+" ORDER BY "+String.join(",",keys))))));}return result;}
 static void persistSessionCustody()throws Exception {if(!Files.exists(sessionCustody))Files.createFile(sessionCustody,java.nio.file.attribute.PosixFilePermissions.asFileAttribute(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------")));assertFalse(Files.isSymbolicLink(sessionCustody));assertEquals(java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"),Files.getPosixFilePermissions(sessionCustody));Files.writeString(sessionCustody,JSON.writeValueAsString(custodyRows));}
 static String session(JdbcTemplate j,String actor,Map<String,String> sessions)throws Exception {String token=Base64.getUrlEncoder().withoutPadding().encodeToString(SecureRandom.getSeed(32));var custody=new LinkedHashMap<String,String>();custody.put("actor",actor);custody.put("tokenHash",hash(token));custody.put("phase","PREPARED_BEFORE_INSERT");custodyRows.add(custody);persistSessionCustody();sessionWrite.set(true);try{assertEquals(1,j.update("INSERT INTO identity_session(token_hash,enterprise_id,session_generation,csrf_token,issued_at,expires_at) SELECT ?,enterprise_id,session_generation,?,UTC_TIMESTAMP(6)-INTERVAL 1 MINUTE,UTC_TIMESTAMP(6)+INTERVAL 1 HOUR FROM enterprise_identity WHERE enterprise_id=? AND status='ACTIVE'",hash(token),"T".repeat(43),actor));sessions.put(actor,token);custody.put("phase","INSERTED");persistSessionCustody();return token;}finally{sessionWrite.set(false);}}
 static HttpResponse<String> request(String api,String token,String path,String body,String key)throws Exception {var request=HttpRequest.newBuilder(URI.create(api+path)).timeout(Duration.ofSeconds(30)).header("Origin","https://task11-b2.example.invalid").header("X-CSRF-Token","T".repeat(43)).header("Content-Type","application/json").header("Idempotency-Key",key);if(token!=null)request.header("Cookie","__Host-AMA_SESSION="+token);var client=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(5)).followRedirects(HttpClient.Redirect.NEVER).build();try{return client.send(request.POST(HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());}finally{client.shutdownNow();assertTrue(client.awaitTermination(Duration.ofSeconds(5)));}}
